2261	// getFirstAutoIncrementValue returns the next auto increment value for a table that just acquired one through an
2262	// ALTER statement.
2263	// TODO: this could use an index and avoid a full table scan in many cases
2264	func (t *AlterableDoltTable) getFirstAutoIncrementValue(
2265		ctx *sql.Context,
2266		columnName string,
2267		columnType sql.Type,
2268		table *doltdb.Table,
2269	) (uint64, error) {
2270		updatedSch, err := table.GetSchema(ctx)
2271		if err != nil {
2272			return 0, err
2273		}
2274	
2275		rowData, err := table.GetRowData(ctx)
2276		if err != nil {
2277			return 0, err
2278		}
2279	
2280		// Note that we aren't calling the public PartitionRows, because it always gets the table data from the session
2281		// root, which hasn't been updated yet
2282		rowIter, err := partitionRows(ctx, table, t.projectedCols, index.SinglePartition{RowData: rowData})
2283		if err != nil {
2284			return 0, err
2285		}
2286	
2287		initialValue := columnType.Zero()
2288		colIdx := updatedSch.GetAllCols().IndexOf(columnName)
2289	
2290		for {
2291			r, err := rowIter.Next(ctx)
2292			if err == io.EOF {
2293				break
2294			} else if err != nil {
2295				return 0, err
2296			}
2297	
2298			cmp, err := columnType.Compare(ctx, initialValue, r[colIdx])
2299			if err != nil {
2300				return 0, err
2301			}
2302			if cmp < 0 {
2303				initialValue = r[colIdx]
2304			}
2305		}
2306	
2307		seq, err := dsess.CoerceAutoIncrementValue(ctx, initialValue)
2308		if err != nil {
2309			return 0, err
2310		}
2311		seq++
2312	
2313		return seq, nil
2314	}
